	(n, m) = [int(i) for i in input().split()]
	a = []
	num = [0] * n
	for i in range(n):
		a.append([int(i) for i in input().split()])
		num[i] = a[i].count(1)
	count = sum(num)
	if count % n:
		print(-1)
		continue
	count //= n
	mm = 0
	for i in num:
		if i - count > 0:
			mm += i - count
	print(mm)
	(i, j) = (0, 0)
	while True:
		while i < n and num[i] <= count:
			i += 1
		while j < n and num[j] >= count:
			j += 1
		if i >= n or j >= n:
			break
		m = min(num[i] - count, count - num[j])
		num[i] -= m
		num[j] += m
